class Solution {
public:
    std::vector<std::vector<int>> substringXorQueries(std::string s, std::vector<std::vector<int>>& queries) {
        std::unordered_map<int, std::pair<int, int>> seen;
        int n = s.size();
        for (int len = 1; len <= 30; ++len) {
            for (int i = 0; i + len <= n; ++i) {
                int val = 0;
                for (int j = i; j < i + len; ++j) {
                    val = (val << 1) | (s[j] - '0');
                }
                if (seen.find(val) == seen.end()) {
                    seen[val] = {i, i + len - 1};
                }
            }
        }
        std::vector<std::vector<int>> res;
        res.reserve(queries.size());
        for (auto& q : queries) {
            int target = q[0] ^ q[1];
            if (seen.count(target)) {
                res.push_back({seen[target].first, seen[target].second});
            } else {
                res.push_back({-1, -1});
            }
        }
        return res;
    }
};

class Solution {
    public int[][] substringXorQueries(String s, int[][] queries) {
        java.util.Map<Integer, int[]> seen = new java.util.HashMap<>();
        int n = s.length();
        for (int len = 1; len <= 30; len++) {
            for (int i = 0; i + len <= n; i++) {
                int val = 0;
                for (int j = i; j < i + len; j++) {
                    val = (val << 1) | (s.charAt(j) - '0');
                }
                if (!seen.containsKey(val)) {
                    seen.put(val, new int[]{i, i + len - 1});
                }
            }
        }
        int[][] res = new int[queries.length][2];
        for (int i = 0; i < queries.length; i++) {
            int target = queries[i][0] ^ queries[i][1];
            if (seen.containsKey(target)) {
                res[i] = seen.get(target);
            } else {
                res[i] = new int[]{-1, -1};
            }
        }
        return res;
    }
}

